<?php require_once '../config/auth.php';$page_title='Lead';$base='../';$id=(int)($_GET['id']??0);$r=['name'=>'','email'=>'','phone'=>'','company'=>'','source'=>'Website','status'=>'new','estimated_value'=>0,'notes'=>''];if($id){$s=$pdo->prepare('SELECT * FROM leads WHERE id=?');$s->execute([$id]);$r=$s->fetch();}if($_SERVER['REQUEST_METHOD']==='POST'){$d=[trim($_POST['name']),trim($_POST['email']),trim($_POST['phone']),trim($_POST['company']),$_POST['source'],$_POST['status'],(float)$_POST['estimated_value'],trim($_POST['notes'])];if($id)$pdo->prepare('UPDATE leads SET name=?,email=?,phone=?,company=?,source=?,status=?,estimated_value=?,notes=? WHERE id=?')->execute([...$d,$id]);else$pdo->prepare('INSERT INTO leads(name,email,phone,company,source,status,estimated_value,notes,owner_id) VALUES(?,?,?,?,?,?,?,?,?)')->execute([...$d,$_SESSION['user_id']]);header('Location:index.php');exit;}include '../partials/header.php';?><div class="cardx"><h4><?=$id?'Edit':'Add'?> Lead</h4><form method="post"><div class="row g-3 mt-1"><div class="col-md-6"><label>Name</label><input required class="form-control" name="name" value="<?=e($r['name'])?>"></div><div class="col-md-6"><label>Email</label><input class="form-control" name="email" value="<?=e($r['email'])?>"></div><div class="col-md-4"><label>Phone</label><input class="form-control" name="phone" value="<?=e($r['phone'])?>"></div><div class="col-md-4"><label>Company</label><input class="form-control" name="company" value="<?=e($r['company'])?>"></div><div class="col-md-4"><label>Estimated value</label><input class="form-control" type="number" step=".01" name="estimated_value" value="<?=e($r['estimated_value'])?>"></div><div class="col-md-6"><label>Source</label><select class="form-select" name="source"><?php foreach(['Website','Referral','Facebook','Instagram','LinkedIn','Cold Call','Other'] as $x):?><option <?=$r['source']==$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Status</label><select class="form-select" name="status"><?php foreach(['new','contacted','qualified','proposal','converted','lost'] as $x):?><option <?=$r['status']==$x?'selected':''?>><?=$x?></option><?php endforeach;?></select></div><div class="col-12"><label>Notes</label><textarea class="form-control" name="notes"><?=e($r['notes'])?></textarea></div></div><button class="btn btn-primary mt-4">Save lead</button></form></div><?php include '../partials/footer.php';?>